const body = $input.first().json;
const allMatches = Array.isArray(body) ? body : (body.matches || []);

if (allMatches.length === 0) {
  return [{ json: { error: 'Нет матчей от API' } }];
}

const countries = ['Россия', 'Англия', 'Испания', 'Италия', 'Германия', 'Франция'];
const now = Date.now();
const in48h = now + 48 * 60 * 60 * 1000;

const filtered = allMatches.filter(m => {
  const country = m.tournament?.category?.name || '';
  const ts = m.startTimestamp || (m.dateEvent ? Date.parse(m.dateEvent) : NaN);
  return m.status === 'notstarted'
    && countries.includes(country)
    && Number.isFinite(ts) && ts >= now && ts <= in48h;
});

if (filtered.length === 0) {
  return [{ json: { error: 'Нет предстоящих матчей в топ-лигах в ближайшие 48 часов' } }];
}

return filtered
  .sort((a, b) => (a.startTimestamp || 0) - (b.startTimestamp || 0))
  .slice(0, 5)
  .map(m => ({
    json: {
      gameId: m.id,
      homeTeam: m.homeTeam?.name || 'Неизвестно',
      awayTeam: m.awayTeam?.name || 'Неизвестно',
      matchTime: new Date(m.startTimestamp).toLocaleString('ru-RU', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }),
      leagueName: m.tournament?.name || 'Неизвестная лига',
      country: m.tournament?.category?.name || '',
      oddsBase: m.oddsBase || []
    }
  }));

const filtrItems = $('Фильтр матчей').all();
const statsItems = $('Краткая статистика').all();

if (filtrItems.length === 0 || filtrItems[0].json.error) {
  return [{ json: { error: 'Нет матчей для анализа' } }];
}

function extract1x2(oddsBase) {
  const market = (oddsBase || []).find(m =>
    /1X2/i.test(m.group || '') || /1X2|full time/i.test(m.name || ''));
  if (!market || !Array.isArray(market.choices)) return null;
  const out = {};
  market.choices.forEach(c => { out[c.name] = c.decimal ?? c.value ?? '?'; });
  return out;
}

const lines = [];
const limit = Math.min(filtrItems.length, 5);

for (let i = 0; i < limit; i++) {
  const base = filtrItems[i].json;
  const details = statsItems[i]?.json || {};
  const c = extract1x2(base.oddsBase) || {};

  const missing = (details.homeTeam?.lineup?.missingPlayers || []).length
    + (details.awayTeam?.lineup?.missingPlayers || []).length;

  const form = details.pregame?.form || {};
  const h2h = details.pregame?.h2h || {};

  lines.push(
    'Матч ' + (i + 1) + ': ' + base.homeTeam + ' vs ' + base.awayTeam
    + ' (' + base.leagueName + ', ' + base.country + ', начало ' + base.matchTime + ').'
    + ' Кэфы 1X2: П1=' + (c['1'] ?? '?') + ', Х=' + (c['X'] ?? '?') + ', П2=' + (c['2'] ?? '?') + '.'
    + ' Форма: ' + JSON.stringify(form).slice(0, 400) + '.'
    + ' H2H: ' + JSON.stringify(h2h).slice(0, 300) + '.'
    + ' Вне игры/травмы: ' + missing + '.'
  );
}

const selectionPrompt = [
  'Ты спортивный аналитик. Вот ' + lines.length + ' матча:',
  lines.join('\n'),
  '',
  'ТВОЯ ЗАДАЧА:',
  'Выбери ОДИН лучший матч для анализа. Если данные слабые, напиши ТОЛЬКО: НЕТ ПОДХОДЯЩИХ МАТЧЕЙ',
  'Отвечай СТРОГО на русском языке.',
  'Последней строкой ответа напиши ТОЧНО в формате: Лучший матч: N  (где N — номер матча из списка).'
].join('\n');

return [{ json: { raw_data_for_qwen: selectionPrompt } }];

