const qwenResp = $('qwen3.5:4b').first().json;
const qwenText = qwenResp.message?.content || qwenResp.choices?.[0]?.message?.content || '';

const m = qwenText.match(/(?:лучший матч|матч)\s*[:№]?\s*(\d{1,2})/i);
if (!m) {
  return [{ json: { error: 'Не удалось определить номер матча', qwenText: qwenText.slice(0, 500) } }];
}

const selectedIndex = parseInt(m[1], 10) - 1;
const filtrItems = $('Фильтр матчей').all();

if (selectedIndex < 0 || selectedIndex >= filtrItems.length) {
  return [{ json: { error: 'Номер матча вне диапазона', selectedIndex: selectedIndex + 1 } }];
}

return [{ json: { gameId: filtrItems[selectedIndex].json.gameId } }];

const details = $input.first().json;
const home = details.homeTeam || {};
const away = details.awayTeam || {};
const oddsBase = details.oddsBase || [];
const oddsBk = details.oddsBk || {};
const pregame = details.pregame || {};
const missingHome = home.lineup?.missingPlayers || [];
const missingAway = away.lineup?.missingPlayers || [];

function formatMarket(market) {
  const choices = (market.choices || [])
    .map(c => c.name + '@' + (c.decimal ?? c.value ?? '?'))
    .join(', ');
  return 'Рынок: ' + market.name + ' (' + (market.group || 'общий') + ') | Выборы: ' + choices;
}

const baseMarkets = oddsBase.map(formatMarket).join('\n');

let bkMarkets = '';
if (oddsBk && typeof oddsBk === 'object') {
  const bkParts = [];
  for (const [bookmaker, data] of Object.entries(oddsBk)) {
    if (data && Array.isArray(data.markets)) {
      bkParts.push('--- ' + bookmaker.toUpperCase() + ' ---');
      bkParts.push(data.markets.map(formatMarket).join('\n'));
    }
  }
  bkMarkets = bkParts.join('\n');
}

const referee = details.referee;
const refereeText = referee
  ? 'Судья: ' + referee.name + '. Карточек за матч: ' + (referee.cardsPerMatch ?? referee.yellowCards ?? 'н/д')
  : 'Судья: нет данных';

const prompt = [
  'Детальный анализ матча: ' + (home.name || '?') + ' vs ' + (away.name || '?'),
  '',
  'КОЭФФИЦИЕНТЫ (базовые):',
  baseMarkets || 'Нет данных',
  '',
  'РАСШИРЕННЫЕ РЫНКИ (букмекеры):',
  bkMarkets || 'Нет данных',
  '',
  'ФОРМА ХОЗЯЕВ:',
  JSON.stringify(pregame.form?.homeTeam || pregame.form || {}),
  '',
  'ФОРМА ГОСТЕЙ:',
  JSON.stringify(pregame.form?.awayTeam || {}),
  '',
  'ОЧНЫЕ ВСТРЕЧИ:',
  JSON.stringify(pregame.h2h || {}),
  '',
  'СЕРИИ КОМАНД:',
  JSON.stringify(pregame.teamStreaks || {}),
  '',
  'ТРАВМЫ ХОЗЯЕВ: ' + (missingHome.map(p => p.player?.name).join(', ') || 'нет'),
  'ТРАВМЫ ГОСТЕЙ: ' + (missingAway.map(p => p.player?.name).join(', ') || 'нет'),
  '',
  refereeText,
  '',
  'Твоя задача:',
  '1. Проанализируй все доступные рынки.',
  '2. Выбери три самых перспективных рынка (исход, тотал, фора, обе забьют, карточки и т.д.).',
  '3. Для каждого укажи: Рынок: [название] | Прогноз: [значение] | Уверенность: [X]/10 | Обоснование: [одно предложение].',
  '4. Отвечай СТРОГО на русском языке.',
  '5. Не делай сложных математических вычислений.'
].join('\n');

return [{ json: { raw_data_for_deepseek: prompt } }];

