const raw = $input.first().json;

const aiText = raw.choices?.[0]?.message?.content
  || raw.message?.content
  || raw.output
  || raw.text
  || (raw.error ? 'ОШИБКА API: ' + JSON.stringify(raw.error) : 'Структура ответа неизвестна: ' + JSON.stringify(raw).slice(0, 500));

return [{
  json: {
    'СТАТУС': '✅ Готово',
    'ПРОГНОЗ': aiText
  }
}];
